 IF (FOUND AND (NEW.version<>latest.version+1 OR NEW.kind<>latest.kind)) OR (NOT FOUND AND NEW.version<>1) THEN
  RAISE EXCEPTION 'credential purpose requires the next immutable version' USING ERRCODE='23514';END IF;
 RETURN NEW;
END

